  const heap = [];

  const bubbleUp = (idx) => {
    while (idx > 0) {
      const parentIdx = Math.floor((idx - 1) / 2);
      if (heap[idx].priorite < heap[parentIdx].priorite) {
        [heap[idx], heap[parentIdx]] = [heap[parentIdx], heap[idx]];
        idx = parentIdx;
      } else {
        break;
      }
    }
  };

  const bubbleDown = (idx) => {
    const length = heap.length;
    while (true) {
      let smallest = idx;
      const left = 2 * idx + 1;
      const right = 2 * idx + 2;

      if (left < length && heap[left].priorite < heap[smallest].priorite) {
        smallest = left;
      }
      if (right < length && heap[right].priorite < heap[smallest].priorite) {
        smallest = right;
      }

      if (smallest !== idx) {
        [heap[idx], heap[smallest]] = [heap[smallest], heap[idx]];
        idx = smallest;
      } else {
        break;
      }
    }
  };

  return {
    enqueue: (val, priorite) => {
      heap.push({ val, priorite });
      bubbleUp(heap.length - 1);
    },
    dequeue: () => {
      if (heap.length === 0) return undefined;
      const root = heap[0];
      const last = heap.pop();
      if (heap.length > 0) {
