    return Math.floor((i - 1) / 2);
  }

  function getLeftChildIndex(i) {
    return 2 * i + 1;
  }

  function getRightChildIndex(i) {
    return 2 * i + 2;
  }

  function swap(i, j) {
    const temp = heap[i];
    heap[i] = heap[j];
    heap[j] = temp;
  }

  function bubbleUp(index) {
    let currentIndex = index;
    while (currentIndex > 0) {
      const parentIndex = getParentIndex(currentIndex);
      if (heap[currentIndex].priorite < heap[parentIndex].priorite) {
        swap(currentIndex, parentIndex);
        currentIndex = parentIndex;
      } else {
        break;
      }
    }
  }

  function bubbleDown(index) {
    let currentIndex = index;
    const length = heap.length;
    while (getLeftChildIndex(currentIndex) < length) {
      let leftChildIndex = getLeftChildIndex(currentIndex);
      let rightChildIndex = getRightChildIndex(currentIndex);
      let smallestChildIndex = leftChildIndex;

      if (rightChildIndex < length && heap[rightChildIndex].priorite < heap[leftChildIndex].priorite) {
        smallestChildIndex = rightChildIndex;
      }

      if (heap[currentIndex].priorite > heap[smallestChildIndex].priorite) {
        swap(currentIndex, smallestChildIndex);
        currentIndex = smallestChildIndex;
      } else {
        break;
      }
    }
