async function chargerEnParallele(urls, chargement) {
  const succes = [];
  const echecs = [];

  const results = await Promise.allSettled(
    urls.map(async (url) => {
      const result = await chargement(url);
      return { url, result };
    })
  );

  for (let i = 0; i < results.length; i++) {
    if (results[i].status === 'fulfilled') {
      succes.push(results[i].value.result);
    } else {
      echecs.push(urls[i]);
    }
  }

  return { succes, echecs };
}
