function creerSubject() {
  const subscribers = [];
  let completed = false;
  let errorValue = null;

  return {
    next(val) {
      if (completed) return;
      subscribers.forEach(sub => {
        if (sub.next) sub.next(val);
      });
    },
    error(err) {
      if (completed) return;
      completed = true;
      errorValue = err;
      subscribers.forEach(sub => {
        if (sub.error) sub.error(err);
      });
    },
    complete() {
      if (completed) return;
      completed = true;
      subscribers.forEach(sub => {
        if (sub.complete) sub.complete();
      });
    },
    subscribe(observer) {
      subscribers.push(observer);
      return {
        unsubscribe() {
          const index = subscribers.indexOf(observer);
          if (index > -1) {
            subscribers.splice(index, 1);
          }
        }
      };
    }
  };
}
```

