function creerCircuitBreaker(fn, seuil, delaiResetMs) {
  let echecsConsecutifs = 0;
  let etat = 'ferme';
  let timerReset = null;

  return async function(...args) {
    if (etat === 'ouvert') {
      throw new Error('Circuit breaker ouvert');
    }

    if (etat === 'semi-ouvert') {
      try {
        const result = await fn(...args);
        etat = 'ferme';
        echecsConsecutifs = 0;
        return result;
      } catch (err) {
        etat = 'ouvert';
        clearTimeout(timerReset);
        timerReset = setTimeout(() => {
          etat = 'semi-ouvert';
        }, delaiResetMs);
        throw err;
      }
    }

    try {
      const result = await fn(...args);
      echecsConsecutifs = 0;
      return result;
    } catch (err) {
      echecsConsecutifs++;

      if (echecsConsecutifs >= seuil) {
        etat = 'ouvert';
        timerReset = setTimeout(() => {
          etat = 'semi-ouvert';
        }, delaiResetMs);
      }

      throw err;
    }
  };
}
