function dijkstra(graphe, depart) {
  const distances = {};
  const visites = new Set();
  const filePriorite = [];

  for (const noeud in graphe) {
    distances[noeud] = Infinity;
  }
  distances[depart] = 0;
  filePriorite.push({ noeud: depart, distance: 0 });

  while (filePriorite.length > 0) {
    filePriorite.sort((a, b) => a.distance - b.distance);
    const actuel = filePriorite.shift();
    const noeudActuel = actuel.noeud;

    if (visites.has(noeudActuel)) continue;
    visites.add(noeudActuel);

    const voisins = graphe[noeudActuel] || {};
    for (const voisin in voisins) {
      const poids = voisins[voisin];
      const nouvelleDistance = distances[noeudActuel] + poids;
      if (nouvelleDistance < distances[voisin]) {
        distances[voisin] = nouvelleDistance;
        filePriorite.push({ noeud: voisin, distance: nouvelleDistance });
      }
    }
  }

  return distances;
}
