function fusionnerIntervalles(tab) {
    if (tab.length === 0) return [];
    tab.sort((a, b) => a[0] - b[0]);
    const result = [tab[0].slice()];
    for (let i = 1; i < tab.length; i++) {
        const last = result[result.length - 1];
        if (tab[i][0] <= last[1]) {
            last[1] = Math.max(last[1], tab[i][1]);
        } else {
            result.push(tab[i].slice());
        }
    }
    return result;
}

function prefixeCommun(tab) {
    if (tab.length === 0) return '';
    let prefix = tab[0];
    for (let i = 1; i < tab.length; i++) {
        while (tab[i].indexOf(prefix) !== 0) {
            prefix = prefix.slice(0, -1);
            if (prefix === '') return '';
        }
    }
    return prefix;
}

function nombreDeBits1(n) {
    let count = 0;
    while (n > 0) {
        count += n & 1;
        n = n >>> 1;
    }
    return count;
}

function medianeDeuxTries(a, b) {
    const merged = [];
    let i = 0, j = 0;
    while (i < a.length && j < b.length) {
        if (a[i] <= b[j]) {
            merged.push(a[i++]);
        } else {
            merged.push(b[j++]);
        }
    }
    while (i < a.length) merged.push(a[i++]);
    while (j < b.length) merged.push(b[j++]);
    const mid = Math.floor(merged.length / 2);
    if (merged.length % 2 === 0) {
        return (merged[mid - 1] + merged[mid]) / 2;
    }
    return merged[mid];
}

function plusLongueSousSuiteCroissante(tab) {
    if (tab.length === 0) return 0;
    const dp = new Array(tab.length).fill(1);
    for (let i = 1; i < tab.length; i++) {
        for (let j = 0; j < i; j++) {
            if (tab[j] < tab[i]) {
                dp[i] = Math.max(dp[i], dp[j] + 1);
            }
        }
    }
    return Math.max(...dp);
}
